import { readFile, writeFile } from 'fs/promises';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'app/data.json');

export async function getNotificationPreference() {
  try {
    const data = await readFile(DB_PATH, 'utf-8');
    return JSON.parse(data).notificationsEnabled;
  } catch (error) {
    return false;
  }
}

export async function toggleNotificationPreferenceDb() {
  const current = await getNotificationPreference();
  const newData = { notificationsEnabled: !current };
  await writeFile(DB_PATH, JSON.stringify(newData, null, 2));
  return newData.notificationsEnabled;
}

