'use server';

import { revalidatePath } from 'next/cache';
import { toggleNotificationPreferenceDb } from './db';

export async function toggleNotifications() {
  await toggleNotificationPreferenceDb();
  // This is the key part: revalidate the path to refresh the data on the page
  revalidatePath('/');
}

import { getNotificationPreference } from './db';
import { toggleNotifications } from './actions';

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Settings</h1>

      <div style={{ 
        border: '1px solid #ccc', 
        padding: '1rem', 
        borderRadius: '8px',
        maxWidth: '400px'
      }}>
        <h2>Notification Preferences</h2>
        <p>
          Status: <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>
        </p>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: notificationsEnabled ? '#ef4444' : '#22c55e',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Turn {notificationsEnabled ? 'Off' : 'On'}
          </button>
        </form>

        <p style={{ fontSize: '0.8rem', color: '#666', marginTop: '1rem' }}>
          Clicking the button will toggle the preference and refresh the page automatically using revalidatePath.
        </p>
      </div>
    </main>
  );
}

